package com.emergentcity.city;

import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.tags.BlockTags;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.levelgen.Heightmap;

/**
 * Reads the world into terrain data, one chunk at a time within a per-tick time budget (chunks that
 * do not exist yet are generated by getChunk). Per column it records the ground level (top solid
 * block, ignoring trees and plants), the top of any vegetation (for clearing), and water.
 */
public final class TerrainSampler {
    final ServerLevel level;
    public final int ox, oz, cols, rows, minY;
    public final int[] ground, clearTop;
    public final boolean[] water;
    /** Columns topped by something man-made (an existing village, an earlier city, a player's build). */
    final boolean[] structure;
    private final int cx0, cz0, cx1, cz1;
    private int cx, cz;
    int chunksDone;
    final int chunksTotal;
    /**
     * Plague mode's newcomers: what is left of the old town is just more ground to them (man-made blocks count as ground),
     * except in these columns, which they leave alone (read down to the ground the ruin stands on, as for any structure).
     */
    boolean ruinsAsGround;
    boolean[] respect;

    /** Read the whole area again (for a new town on the same site). */
    void restart(boolean ruinsAsGround, boolean[] respect) {
        this.ruinsAsGround = ruinsAsGround;
        this.respect = respect;
        cx = cx0; cz = cz0;
        chunksDone = 0;
        java.util.Arrays.fill(structure, false);
    }

    TerrainSampler(ServerLevel level, int ox, int oz, int cols, int rows) {
        this.level = level; this.ox = ox; this.oz = oz; this.cols = cols; this.rows = rows;
        minY = level.getMinBuildHeight();
        ground = new int[cols * rows];
        clearTop = new int[cols * rows];
        water = new boolean[cols * rows];
        structure = new boolean[cols * rows];
        cx0 = ox >> 4; cz0 = oz >> 4; cx1 = (ox + cols - 1) >> 4; cz1 = (oz + rows - 1) >> 4;
        cx = cx0; cz = cz0;
        chunksTotal = (cx1 - cx0 + 1) * (cz1 - cz0 + 1);
    }

    static boolean isVegetation(BlockState s) {
        return s.isAir() || s.canBeReplaced() || s.is(BlockTags.LOGS) || s.is(BlockTags.LEAVES)
                || s.is(Blocks.CACTUS) || s.is(Blocks.SUGAR_CANE) || s.is(Blocks.BAMBOO)
                || s.is(Blocks.MUSHROOM_STEM) || s.is(Blocks.BROWN_MUSHROOM_BLOCK) || s.is(Blocks.RED_MUSHROOM_BLOCK)
                || s.is(Blocks.BEE_NEST) || s.is(Blocks.MOSS_CARPET) || s.is(Blocks.SNOW);
    }

    /** Returns true when all chunks are sampled. */
    boolean tick(long budgetNanos) {
        long end = System.nanoTime() + budgetNanos;
        BlockPos.MutableBlockPos mp = new BlockPos.MutableBlockPos();
        while (cz <= cz1) {
            level.getChunk(cx, cz); // loads or generates the chunk
            for (int x = Math.max(ox, cx << 4); x <= Math.min(ox + cols - 1, (cx << 4) + 15); x++)
                for (int z = Math.max(oz, cz << 4); z <= Math.min(oz + rows - 1, (cz << 4) + 15); z++) sampleColumn(x, z, mp);
            chunksDone++;
            if (++cx > cx1) { cx = cx0; cz++; }
            if (System.nanoTime() > end) return cz > cz1;
        }
        return true;
    }

    /** Building materials that do not occur naturally at the surface. */
    static boolean isManMade(BlockState s) {
        return s.is(BlockTags.PLANKS) || s.is(BlockTags.STAIRS) || s.is(BlockTags.SLABS) || s.is(BlockTags.WALLS)
                || s.is(BlockTags.FENCES) || s.is(BlockTags.DOORS) || s.is(BlockTags.BEDS) || s.is(BlockTags.WOOL)
                || s.is(BlockTags.STONE_BRICKS) || s.is(Blocks.BRICKS) || s.is(Blocks.GLASS) || s.is(Blocks.GLASS_PANE)
                || s.is(Blocks.COBBLESTONE) || s.is(Blocks.BOOKSHELF) || s.is(Blocks.CRAFTING_TABLE) || s.is(Blocks.GLOWSTONE);
    }

    private void sampleColumn(int x, int z, BlockPos.MutableBlockPos mp) {
        int k = (z - oz) * cols + (x - ox);
        int y = level.getHeight(Heightmap.Types.WORLD_SURFACE, x, z) - 1;
        clearTop[k] = y;
        boolean w = false, built = false;
        int below = 0;
        while (y > minY) {
            BlockState s = level.getBlockState(mp.set(x, y, z));
            if (!s.getFluidState().isEmpty() || s.is(BlockTags.ICE)) { w = true; break; }
            if (isVegetation(s)) { y--; continue; }
            // a structure: remember it and keep going down to the natural ground it stands on (bounded)
            if (isManMade(s) && below < 40 && (!ruinsAsGround || (respect != null && respect[k]))) { built = !ruinsAsGround; below++; y--; continue; }
            break;
        }
        ground[k] = y;
        water[k] = w;
        structure[k] = built;
    }

    double progress() { return chunksDone / (double) chunksTotal; }

    /**
     * Villager mode: re-read the world around a surveyor before it decides, so streets respond to the
     * terrain as it is now (including anything a player changed). Cells in keep (finished buildings) are
     * not re-read, since their roofs are not ground. Updates the smoothed simulation heights in place.
     */
    void refreshPatch(Terrain t, int wx, int wz, int r, int blur, boolean[] keep, boolean[] keep2) {
        BlockPos.MutableBlockPos mp = new BlockPos.MutableBlockPos();
        int ci = wx - ox, cj = wz - oz, m = r + blur;
        for (int j = Math.max(0, cj - m); j <= Math.min(rows - 1, cj + m); j++)
            for (int i = Math.max(0, ci - m); i <= Math.min(cols - 1, ci + m); i++) {
                int k = j * cols + i;
                if ((keep != null && keep[k]) || (keep2 != null && keep2[k])) continue;
                sampleColumn(ox + i, oz + j, mp);
            }
        for (int j = Math.max(0, cj - r); j <= Math.min(rows - 1, cj + r); j++)
            for (int i = Math.max(0, ci - r); i <= Math.min(cols - 1, ci + r); i++) {
                double sum = 0;
                int cnt = 0;
                for (int dj = -blur; dj <= blur; dj++) for (int di = -blur; di <= blur; di++) {
                    int ii = i + di, jj = j + dj;
                    if (ii < 0 || jj < 0 || ii >= cols || jj >= rows) continue;
                    sum += ground[jj * cols + ii];
                    cnt++;
                }
                int k = j * cols + i;
                t.h[k] = (float) (sum / cnt);
                t.water[k] = water[k];
            }
    }

    /** Builds the simulation terrain (1 cell = 1 block), with heights smoothed so slopes are not 1-block noise. */
    /** Structure columns grown by one block, so the town never builds flush against an existing building. */
    boolean[] keepOut() {
        boolean[] k = new boolean[structure.length];
        for (int j = 0; j < rows; j++) for (int i = 0; i < cols; i++) {
            if (!structure[j * cols + i]) continue;
            for (int dj = -1; dj <= 1; dj++) for (int di = -1; di <= 1; di++) {
                int ii = i + di, jj = j + dj;
                if (ii >= 0 && jj >= 0 && ii < cols && jj < rows) k[jj * cols + ii] = true;
            }
        }
        return k;
    }

    Terrain toTerrain(int blur, String name) {
        Terrain t = new Terrain(name, cols, rows, 1.0);
        float[] h = new float[cols * rows];
        for (int k = 0; k < h.length; k++) h[k] = ground[k];
        h = boxBlur(boxBlur(h, blur, true), blur, false);
        System.arraycopy(h, 0, t.h, 0, h.length);
        System.arraycopy(water, 0, t.water, 0, water.length);
        t.description = "sampled from the Minecraft world";
        return t;
    }

    private float[] boxBlur(float[] in, int r, boolean horizontal) {
        if (r <= 0) return in;
        float[] out = new float[in.length];
        for (int j = 0; j < rows; j++) for (int i = 0; i < cols; i++) {
            double s = 0;
            int c = 0;
            for (int d = -r; d <= r; d++) {
                int ii = horizontal ? i + d : i, jj = horizontal ? j : j + d;
                if (ii < 0 || jj < 0 || ii >= cols || jj >= rows) continue;
                s += in[jj * cols + ii];
                c++;
            }
            out[j * cols + i] = (float) (s / c);
        }
        return out;
    }
}
